import os
import hashlib
import hmac
import unicodedata
from flask import Flask, request, jsonify, send_file, abort
from functools import wraps
import re

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', os.urandom(32).hex())
app.config['UPLOAD_DIR'] = os.environ.get('UPLOAD_DIR', '/var/app/uploads')
app.config['MAX_PATH_LEN'] = 255

# Security: allowed file extensions
ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.doc', '.csv'}

# Security: blocked path components
BLOCKED_PATTERNS = [
    re.compile(r'\.\./'),
    re.compile(r'/\.\./'),
    re.compile(r'\\'),
    re.compile(r'%2e%2e', re.IGNORECASE),
    re.compile(r'%2f', re.IGNORECASE),
]

def verify_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key', '')
        expected = app.config['SECRET_KEY']
        if not hmac.compare_digest(api_key, expected):
            abort(401)
        return f(*args, **kwargs)
    return decorated

def validate_filename(filename):
    """Validate filename for security.
    Returns sanitized filename or None if invalid."""
    if not filename or len(filename) > app.config['MAX_PATH_LEN']:
        return None

    # Check for blocked patterns in raw input
    for pattern in BLOCKED_PATTERNS:
        if pattern.search(filename):
            return None

    # Check for null bytes
    if '\x00' in filename:
        return None

    # Reject absolute paths
    if filename.startswith('/'):
        return None

    # Validate extension
    _, ext = os.path.splitext(filename)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        return None

    return filename

def safe_path_join(base_dir, filename):
    """Safely join base directory with filename.
    Performs path traversal check AFTER normalization."""
    # Normalize unicode to NFC form
    normalized = unicodedata.normalize('NFC', filename)

    # Construct full path
    full_path = os.path.normpath(os.path.join(base_dir, normalized))

    # Verify the resolved path is within base_dir
    base_resolved = os.path.normpath(base_dir)
    if not full_path.startswith(base_resolved + os.sep) and full_path != base_resolved:
        return None

    return full_path

@app.route('/api/files/<path:filename>', methods=['GET'])
@verify_api_key
def get_file(filename):
    """Retrieve a file from the uploads directory."""
    # Step 1: Validate the raw filename
    validated = validate_filename(filename)
    if validated is None:
        abort(400, description='Invalid filename')

    # Step 2: Normalize unicode AFTER validation
    # This ensures consistent storage lookup
    normalized_name = unicodedata.normalize('NFKC', validated)

    # Step 3: Safe path construction
    file_path = safe_path_join(app.config['UPLOAD_DIR'], normalized_name)
    if file_path is None:
        abort(403, description='Access denied')

    # Step 4: Check file exists
    if not os.path.isfile(file_path):
        abort(404)

    return send_file(file_path)

@app.route('/api/files', methods=['POST'])
@verify_api_key
def upload_file():
    """Upload a file to the uploads directory."""
    if 'file' not in request.files:
        abort(400, description='No file provided')

    file = request.files['file']
    filename = file.filename

    validated = validate_filename(filename)
    if validated is None:
        abort(400, description='Invalid filename')

    # Normalize for storage
    normalized_name = unicodedata.normalize('NFKC', validated)

    file_path = safe_path_join(app.config['UPLOAD_DIR'], normalized_name)
    if file_path is None:
        abort(403, description='Access denied')

    file.save(file_path)
    return jsonify({'status': 'uploaded', 'filename': normalized_name}), 201

@app.route('/api/files/<path:filename>', methods=['DELETE'])
@verify_api_key
def delete_file(filename):
    """Delete a file from the uploads directory."""
    validated = validate_filename(filename)
    if validated is None:
        abort(400, description='Invalid filename')

    normalized_name = unicodedata.normalize('NFKC', validated)

    file_path = safe_path_join(app.config['UPLOAD_DIR'], normalized_name)
    if file_path is None:
        abort(403, description='Access denied')

    if not os.path.isfile(file_path):
        abort(404)

    os.remove(file_path)
    return jsonify({'status': 'deleted'}), 200

if __name__ == '__main__':
    os.makedirs(app.config['UPLOAD_DIR'], exist_ok=True)
    app.run(host='127.0.0.1', port=5000)
